(()=>{
const $=s=>document.querySelector(s),key='api-praktikum-v1',initial=[{id:1,title:'Спроектировать контракт',completed:false},{id:2,title:'Описать ответы API',completed:true},{id:3,title:'Проверить ошибки',completed:false}];let state={tasks:structuredClone(initial),custom:[],solved:[],title:'Task API',version:'1.0.0'};try{const saved=JSON.parse(localStorage.getItem(key)||'null');if(saved)state={...state,...saved};if(!Array.isArray(state.tasks)||!Array.isArray(state.custom)||!Array.isArray(state.solved))throw Error()}catch{state={tasks:structuredClone(initial),custom:[],solved:[],title:'Task API',version:'1.0.0'}}
let active=0,last=null,ready=false,sending=false;const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const exercises=[
{title:'Получить завершённые задачи',text:'Запросите список задач, оставив только завершённые. Используйте GET /tasks с query-параметром completed=true. Ответ должен содержать массив items и статус 200.',hint:'Укажите путь /tasks?completed=true. Тело запроса не нужно.',check:r=>r.method==='GET'&&r.path==='/tasks'&&r.query.get('completed')==='true'&&r.status===200&&Array.isArray(r.data?.items)&&r.data.items.every(t=>t.completed)},
{title:'Создать новую задачу',text:'Спроектируйте запрос создания задачи. Отправьте POST /tasks с непустым полем title. Проверьте, что сервер вернул 201 и присвоил задаче id.',hint:'Тело: {"title":"Изучить REST"}. Content-Type: application/json.',check:r=>r.method==='POST'&&r.path==='/tasks'&&r.status===201&&typeof r.data?.id==='number'&&!!r.data?.title},
{title:'Обновить часть ресурса',text:'Завершите задачу: отправьте PATCH /tasks/{id}, установив completed в true. Используйте id существующей задачи. Сервер должен вернуть обновлённый ресурс и статус 200.',hint:'Например PATCH /tasks/1 с телом {"completed":true}. Список существующих id можно получить через GET /tasks.',check:r=>r.method==='PATCH'&&/^\/tasks\/\d+$/.test(r.path)&&r.status===200&&r.sent?.completed===true&&r.data?.completed===true},
{title:'Удалить ресурс',text:'Удалите существующую задачу с помощью DELETE /tasks/{id}. Правильный ответ — 204 No Content без тела.',hint:'Отправьте DELETE /tasks/3. Если она уже удалена, выберите другой id или сбросьте учебные данные.',check:r=>r.method==='DELETE'&&/^\/tasks\/\d+$/.test(r.path)&&r.status===204&&r.text===''},
{title:'Проверить валидацию',text:'Проверьте обработку ошибки: отправьте POST /tasks без обязательного поля title. Ожидайте статус 422 и код validation_error.',hint:'Отправьте пустой JSON-объект {}. Неверный синтаксис JSON даст другую ошибку — 400.',check:r=>r.method==='POST'&&r.path==='/tasks'&&r.status===422&&r.data?.error==='validation_error'},
{title:'Спроектировать свой эндпоинт',text:'Во вкладке «Проектирование» создайте GET /health с ответом 200 и JSON {"status":"ok"}. Затем выполните запрос к нему. Найдите новый контракт во вкладке «Документация».',hint:'Укажите метод GET, путь /health, описание, статус 200 и пример ответа. Сохраните, затем отправьте GET /health.',check:r=>r.method==='GET'&&r.path==='/health'&&r.status===200&&r.data?.status==='ok'&&state.custom.some(e=>e.method==='GET'&&e.path==='/health')}
];
const taskSchema={type:'object',required:['id','title','completed'],properties:{id:{type:'integer',example:1},title:{type:'string',example:'Изучить REST'},completed:{type:'boolean',example:false}}};
const builtins=[{method:'GET',path:'/tasks',summary:'Список задач',status:200,response:{items:initial,total:3}},{method:'GET',path:'/tasks/{id}',summary:'Задача по id',status:200,response:initial[0]},{method:'POST',path:'/tasks',summary:'Создать задачу',status:201,response:{id:4,title:'Новая задача',completed:false}},{method:'PUT',path:'/tasks/{id}',summary:'Заменить задачу целиком',status:200,response:initial[0]},{method:'PATCH',path:'/tasks/{id}',summary:'Частично обновить задачу',status:200,response:{...initial[0],completed:true}},{method:'DELETE',path:'/tasks/{id}',summary:'Удалить задачу',status:204,response:null}];
function persist(){try{localStorage.setItem(key,JSON.stringify(state))}catch{$('#engine-status').textContent='Не удалось сохранить в браузере'}}
function progress(){$('#api-progress').textContent=state.solved.length+' / '+exercises.length;$('#exercise').innerHTML=exercises.map((e,i)=>`<option value="${i}" ${i===active?'selected':''}>${state.solved.includes(i)?'✓ ':''}${i+1}. ${esc(e.title)}</option>`).join('')}
function choose(i){active=i;const e=exercises[i];$('#exercise-title').textContent=e.title;$('#exercise-text').textContent=e.text;$('#exercise-hint').textContent=e.hint;$('#exercise-result').textContent='';progress()}
function tab(name){document.querySelectorAll('[data-tab]').forEach(b=>{b.classList.toggle('active',b.dataset.tab===name);b.setAttribute('aria-selected',String(b.dataset.tab===name))});for(const n of ['request','design','docs'])$('#'+n+'-panel').hidden=n!==name;if(name==='docs')renderDocs()}
function useEndpoint(e){tab('request');$('#method').value=e.method;$('#request-path').value=e.path.replace(/\{[^}]+\}/g,String(state.tasks[0]?.id||1));$('#request-body').value=['POST','PUT','PATCH'].includes(e.method)?JSON.stringify(e.path.startsWith('/tasks')?(e.method==='POST'?{title:'Новая задача'}:e.method==='PUT'?{title:'Обновлённая задача',completed:false}:{completed:true}):Object.fromEntries((e.required||[]).map(k=>[k,'пример'])),null,2):'';$('#request-path').focus()}
function renderEndpoints(){$('#endpoint-list').innerHTML=[...builtins,...state.custom].map((e,i)=>`<button class="endpoint" data-endpoint="${i}"><span class="method-label ${e.method}">${e.method}</span><code>${esc(e.path)}</code></button>`).join('');$('#custom-endpoints').innerHTML=state.custom.length?state.custom.map((e,i)=>`<div class="custom-row"><span class="method-label ${e.method}">${e.method}</span><code>${esc(e.path)}</code><button data-edit="${i}">Изменить</button><button data-delete="${i}">Удалить</button></div>`).join(''):'<p>Пока нет своих эндпоинтов. Создайте первый выше.</p>'}
function infer(value){if(value===null)return {nullable:true};if(Array.isArray(value))return {type:'array',items:value.length?infer(value[0]):{}};if(typeof value==='object')return {type:'object',properties:Object.fromEntries(Object.entries(value).map(([k,v])=>[k,infer(v)]))};return {type:typeof value==='number'?(Number.isInteger(value)?'integer':'number'):typeof value==='boolean'?'boolean':'string'}}
function openapi(){const paths={};for(const e of [...builtins,...state.custom]){const isBuiltin=builtins.includes(e),parameters=[];for(const p of e.path.matchAll(/\{([^}]+)\}/g))parameters.push({in:'path',name:p[1],required:true,schema:{type:isBuiltin?'integer':'string'}});if(e.method==='GET'&&e.path==='/tasks')parameters.push({in:'query',name:'completed',required:false,schema:{type:'boolean'},description:'Фильтр по состоянию задачи'});const op={summary:e.summary,...parameters.length?{parameters}:{},responses:{[e.status]:{description:e.status===204?'Ресурс удалён, без тела ответа':'Ответ сервиса',...e.status===204?{}:{content:{'application/json':{schema:infer(e.response),example:e.response}}}}}};if(['POST','PUT','PATCH'].includes(e.method)||e.required?.length){const props=isBuiltin?{title:{type:'string',minLength:1},completed:{type:'boolean'}}:Object.fromEntries((e.required||[]).map(k=>[k,{}]));const required=isBuiltin?(e.method==='POST'?['title']:e.method==='PUT'?['title','completed']:[]):e.required;op.requestBody={required:true,content:{'application/json':{schema:{type:'object',properties:props,...required?.length?{required}:{}},example:isBuiltin?(e.method==='POST'?{title:'Новая задача'}:e.method==='PUT'?{title:'Задача',completed:false}:{completed:true}):Object.fromEntries((required||[]).map(k=>[k,'пример']))}}};op.responses['422']={description:'Не прошла проверка полей',content:{'application/json':{example:{error:'validation_error',message:'Проверьте обязательные поля'}}}};op.responses['400']={description:'Некорректный JSON'}}if(e.path.includes('{'))op.responses['404']={description:'Ресурс не найден'};(paths[e.path]||={})[e.method.toLowerCase()]=op;}return {openapi:'3.0.3',info:{title:state.title||'Task API',version:state.version||'1.0.0',description:'Учебный контракт. Замените пример адреса сервера при реализации API.'},servers:[{url:'https://api.example.com/v1',description:'Пример адреса — замените вашим сервером'}],paths}}
function renderDocs(){const spec=openapi();$('#docs-list').innerHTML=[...builtins,...state.custom].map(e=>`<article class="doc-card"><h3><span class="method-label ${e.method}">${e.method}</span> ${esc(e.path)}</h3><p>${esc(e.summary)}</p><p>Ответ: <strong>${e.status}</strong>${e.required?.length?' · Обязательные поля: '+esc(e.required.join(', ')):''}</p><pre>${e.status===204?'Без тела ответа':esc(JSON.stringify(e.response,null,2))}</pre></article>`).join('');$('#openapi-json').textContent=JSON.stringify(spec,null,2)}
function configure(){return new Promise((resolve,reject)=>{if(!navigator.serviceWorker.controller)return reject(Error('Перезагрузите страницу, чтобы активировать учебный API.'));const channel=new MessageChannel(),timeout=setTimeout(()=>reject(Error('Учебный API не отвечает. Обновите страницу.')),5000);channel.port1.onmessage=()=>{clearTimeout(timeout);channel.port1.close();resolve()};navigator.serviceWorker.controller.postMessage({type:'configure',tasks:state.tasks,custom:state.custom},[channel.port2])})}
async function send(){if(!ready||sending)return;sending=true;$('#send').disabled=true;$('#send').textContent='Отправка…';$('#exercise-result').textContent='';last=null;let abortTimer;try{const method=$('#method').value,path=$('#request-path').value.trim();if(!path.startsWith('/')||path.startsWith('//')||path.includes('#')||/[\\\s]/.test(path)||path.split('/').some(x=>x==='.'||x==='..'))throw Error('Укажите путь, например /tasks/1. Внешние URL и переходы по каталогам не поддерживаются.');const url=new URL('/api/runtime'+path,location.origin);if(!url.pathname.startsWith('/api/runtime/'))throw Error('Некорректный путь.');const headers=JSON.parse($('#request-headers').value||'{}');if(!headers||typeof headers!=='object'||Array.isArray(headers)||Object.values(headers).some(v=>typeof v!=='string'))throw Error('Заголовки должны быть JSON-объектом со строковыми значениями.');await configure();const start=performance.now(),controller=new AbortController();abortTimer=setTimeout(()=>controller.abort(),10000);const response=await fetch(url,{method,headers,body:method==='GET'?undefined:$('#request-body').value,signal:controller.signal,cache:'no-store'});const text=await response.text();if(response.headers.get('X-Practice-Mode')!=='local-simulation')throw Error('Запрос не попал в учебный API. Обновите страницу.');const snapshot=response.headers.get('X-Practice-State');if(snapshot){state.tasks=JSON.parse(decodeURIComponent(snapshot));persist()}let data,sent;try{data=JSON.parse(text)}catch{}try{sent=JSON.parse($('#request-body').value)}catch{}last={method,path:path.split('?')[0].replace(/\/$/,''),query:new URL(url).searchParams,status:response.status,data,sent,text};$('#response-status').textContent=String(response.status)+' '+({200:'OK',201:'Created',204:'No Content',400:'Bad Request',404:'Not Found',405:'Method Not Allowed',422:'Validation Error'}[response.status]||'Response');$('#response-status').className=response.ok?'ok':'bad';$('#response-timing').textContent=Math.round(performance.now()-start)+' мс · '+new TextEncoder().encode(text).length+' байт';$('#response-body').textContent=text||'Нет тела ответа';$('#response-headers').textContent=[...response.headers].filter(([k])=>k!=='x-practice-state').map(([k,v])=>k+': '+v).join('\n');$('#copy-response').disabled=false;}catch(e){$('#response-status').textContent='Ошибка запроса';$('#response-status').className='bad';$('#response-timing').textContent='';$('#response-body').textContent=e.name==='AbortError'?'Превышено время ожидания. Повторите запрос.':e.message;$('#copy-response').disabled=true;}finally{clearTimeout(abortTimer);sending=false;$('#send').disabled=!ready;$('#send').textContent='Отправить'}}
async function initialize(){if(!('serviceWorker'in navigator)){throw Error('Этот браузер не поддерживает учебный API. Откройте сайт в современном браузере.')}await navigator.serviceWorker.register('/api/sw.js',{scope:'/api/'});await navigator.serviceWorker.ready;if(!navigator.serviceWorker.controller)await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(Error('Обновите страницу для запуска API.')),8000);navigator.serviceWorker.addEventListener('controllerchange',()=>{clearTimeout(timeout);resolve()},{once:true})});ready=true;$('#engine-status').textContent='Песочница готова';$('#send').disabled=false}
$('#exercise').onchange=e=>choose(+e.target.value);document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>tab(b.dataset.tab));$('#send').onclick=send;$('#request-path').onkeydown=e=>{if(e.key==='Enter')send()};$('#check-api').onclick=()=>{const out=$('#exercise-result');if(!last){out.className='';out.textContent='Сначала выполните запрос для этого задания.';return}const success=exercises[active].check(last);out.className=success?'success':'';out.textContent=success?'✓ Задание выполнено. Запрос и ответ соответствуют условию.':'Пока не совпадает. Проверьте метод, путь, тело запроса и статус последнего ответа.';if(success&&!state.solved.includes(active)){state.solved.push(active);persist();progress()}};
$('#endpoint-list').onclick=e=>{const b=e.target.closest('[data-endpoint]');if(b)useEndpoint([...builtins,...state.custom][+b.dataset.endpoint])};$('#copy-response').onclick=async()=>{try{await navigator.clipboard.writeText(last?.text||'');$('#copy-response').textContent='Скопировано';setTimeout(()=>$('#copy-response').textContent='Копировать',1400)}catch{$('#exercise-result').textContent='Выделите и скопируйте текст ответа вручную.'}};
$('#endpoint-form').onsubmit=e=>{e.preventDefault();try{const path=$('#design-path').value.trim().replace(/\/$/,'')||'/',method=$('#design-method').value;if(!/^\/(?:[a-zA-Z0-9_-]+|\{[a-zA-Z_][a-zA-Z0-9_]*\})(?:\/(?:[a-zA-Z0-9_-]+|\{[a-zA-Z_][a-zA-Z0-9_]*\}))*$/.test(path))throw Error('Используйте путь вида /users или /users/{id}.');if(path==='/tasks'||path.startsWith('/tasks/'))throw Error('/tasks зарезервирован для учебных заданий. Используйте другой путь.');const response=JSON.parse($('#design-response').value),required=$('#design-required').value.split(',').map(x=>x.trim()).filter(Boolean);if(required.some(k=>!/^[a-zA-Z_][a-zA-Z0-9_]*$/.test(k)))throw Error('Названия полей: латинские буквы, цифры и подчёркивания.');if(method==='GET'&&required.length)throw Error('У GET нет тела. Уберите обязательные поля запроса.');const endpoint={method,path,summary:$('#design-summary').value.trim(),status:+$('#design-status').value,response,required:[...new Set(required)]};const index=state.custom.findIndex(x=>x.method===method&&x.path===path);if(index>=0)state.custom[index]=endpoint;else state.custom.push(endpoint);persist();renderEndpoints();renderDocs();$('#design-result').textContent='Эндпоинт сохранён. Выберите его слева, чтобы выполнить запрос.';}catch(error){$('#design-result').textContent=error.message}};
$('#custom-endpoints').onclick=e=>{const edit=e.target.closest('[data-edit]'),del=e.target.closest('[data-delete]');if(edit){const x=state.custom[+edit.dataset.edit];$('#design-method').value=x.method;$('#design-path').value=x.path;$('#design-summary').value=x.summary;$('#design-status').value=x.status;$('#design-required').value=x.required.join(', ');$('#design-response').value=JSON.stringify(x.response,null,2);$('#design-path').focus()}if(del){state.custom.splice(+del.dataset.delete,1);persist();renderEndpoints();renderDocs()}};
$('#api-title').value=state.title;$('#api-version').value=state.version;for(const id of ['api-title','api-version'])$('#'+id).oninput=()=>{state.title=$('#api-title').value;state.version=$('#api-version').value;persist();renderDocs()};$('#download-openapi').onclick=()=>{const blob=new Blob([JSON.stringify(openapi(),null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='openapi.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};
$('#reset-data').onclick=()=>$('#api-confirm').showModal();$('#cancel-data-reset').onclick=()=>$('#api-confirm').close();$('#confirm-data-reset').onclick=()=>{state.tasks=structuredClone(initial);last=null;persist();$('#api-confirm').close();$('#exercise-result').className='success';$('#exercise-result').textContent='Учебные данные восстановлены. Можно выполнять запросы.'};
choose(0);renderEndpoints();renderDocs();initialize().catch(e=>{$('#engine-status').textContent='Не подключено';$('#response-body').textContent=e.message});
})();
